// Ported from the Node app's Sequelize model PurchaseOrder (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class PurchaseOrderConfiguration : IEntityTypeConfiguration<PurchaseOrder>
{
    public void Configure(EntityTypeBuilder<PurchaseOrder> builder)
    {
        builder.ToTable("purchase_orders", t =>
        {
            t.HasCheckConstraint("CK_purchase_orders_status", "[status] IN (N'ordered', N'received', N'cancelled')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.SupplierId).HasColumnName("supplier_id");
        builder.Property(e => e.OrderDate).HasColumnName("order_date").HasColumnType("date");
        builder.Property(e => e.ExpectedDate).HasColumnName("expected_date").HasColumnType("date");
        builder.Property(e => e.Status).HasColumnName("status").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'ordered'");
        builder.Property(e => e.ReceivedOn).HasColumnName("received_on").HasColumnType("date");
        builder.Property(e => e.Note).HasColumnName("note").HasColumnType("nvarchar(255)").HasMaxLength(255);
        builder.Property(e => e.CreatedByName).HasColumnName("created_by_name").HasColumnType("nvarchar(100)").HasMaxLength(100);
        builder.HasOne(e => e.Supplier).WithMany(p => p.PurchaseOrders).HasForeignKey(e => e.SupplierId).OnDelete(DeleteBehavior.NoAction);
    }
}
